def fetch_nasdaq_100(url: str = NASDAQ_100_WIKI_URL) -> List[str]:
    """Scrape the NASDAQ-100 constituents table from Wikipedia.

    Uses requests + BeautifulSoup so the HTML response can be mocked in tests
    without requiring a live network call.
    """
    resp = requests.get(url, timeout=30, headers={"User-Agent": "Mozilla/5.0"})
    resp.raise_for_status()
    soup = BeautifulSoup(resp.text, "lxml")

    # The constituents table has a "Ticker" column. Find the first wikitable
    # that contains that column header.
    tickers: List[str] = []
    for table in soup.find_all("table", class_="wikitable"):
        headers = [th.get_text(strip=True) for th in table.find_all("th")]
        # Locate which column index holds the ticker
        ticker_col: Optional[int] = None
        for i, h in enumerate(headers):
            if h.lower() in ("ticker", "symbol", "ticker symbol"):
                ticker_col = i
                break
        if ticker_col is None:
            continue
        # Iterate data rows
        for row in table.find_all("tr")[1:]:
            cells = row.find_all("td")
            if len(cells) <= ticker_col:
                continue
            sym = _clean_symbol(cells[ticker_col].get_text(strip=True))
            if sym and sym.upper() != "NAN":
                tickers.append(sym.replace(".", "-"))
        if tickers:
            break

    if not tickers:
        raise RuntimeError(f"Failed to parse NASDAQ-100 tickers from {url}")
    return tickers


def filter_micro_cap(
    tickers: List[str],
    min_cap_b: float,
    excluded_file: str = "tickers/excluded_micro_cap.txt",
) -> List[str]:
    """Return tickers whose market cap is at or above *min_cap_b* billion.

    Tickers that fail the threshold (or whose cap cannot be determined) are
    written to *excluded_file* for review.  Pass ``min_cap_b=0`` to skip
    filtering entirely.
    """
    if min_cap_b <= 0:
        return tickers

    import yfinance as yf  # runtime dependency

    threshold = min_cap_b * 1e9
    passed: List[str] = []
    excluded: List[str] = []

    for sym in tickers:
        try:
            mc = yf.Ticker(sym).fast_info.market_cap
        except Exception:
            mc = None
        if mc is not None and float(mc) >= threshold:
            passed.append(sym)
        else:
            logger.info("Excluding %s: market_cap=%s < %.2fB", sym, mc, min_cap_b)
            excluded.append(sym)

    if excluded:
        os.makedirs(os.path.dirname(excluded_file) or ".", exist_ok=True)
        with open(excluded_file, "w", encoding="utf-8") as f:
            for t in excluded:
                f.write(t + "\n")
        print(f"Micro-cap filter: excluded {len(excluded)} tickers → {excluded_file}")

    return passed


